mapper.select:
SELECT file_path,
       file_content
FROM sq_skill_file
WHERE user_id = #{userId}
  AND skill_version_id = #{versionId}
  AND file_path = #{path}
  AND del_flag = '0'

mapper.update:
UPDATE sq_skill_grant
SET enabled = #{enabled},
       version = version + 1,
       last_updater_id = #{userId}
WHERE user_id = #{userId}
  AND skill_version_id = #{versionId}
  AND version = #{expectedVersion}
  AND del_flag = '0'

UPDATE sq_skill_version
SET status = 'REVOKED',
       authorization_revision = authorization_revision + 1,
       last_updater_id = #{userId}
WHERE user_id = #{userId}
  AND skill_version_id = #{versionId}
  AND status <> 'REVOKED'
  AND del_flag = '0'

mapper.select:
SELECT catalog_id
FROM sq_scope_skill_catalog
WHERE user_id = #{userId}
  AND scope_id = #{scopeId}
  AND del_flag = '0'
FOR UPDATE
